// Event membership is shared catalog data; personal catch/save data stays separate.
let specialEventPokemon=new Map(),specialEventPokemonLoaded=false,specialEventPokemonLoading=null,specialEventPokemonSaving=false;
function specialEventPokemonHas(eventSlug,catalogSlug){
 return !!catalogSlug&&!!specialEventPokemon.get(String(eventSlug))?.has(String(catalogSlug));
}
async function loadSpecialEventPokemon(){
 if(specialEventPokemonLoading)return specialEventPokemonLoading;
 specialEventPokemonLoading=(async()=>{
   try{
     const rows=[];
     for(let offset=0;;offset+=1000){
       const{data,error}=await sb.from("special_event_pokemon").select("event_slug,catalog_slug").order("event_slug").order("catalog_slug").range(offset,offset+999);
       if(error)throw error;
       rows.push(...(data||[]));
       if(!data||data.length<1000)break;
     }
     const next=new Map();
     for(const row of rows){
       if(!next.has(row.event_slug))next.set(row.event_slug,new Set());
       next.get(row.event_slug).add(row.catalog_slug);
     }
     specialEventPokemon=next;
     specialEventPokemonLoaded=true;
     return true;
   }catch(err){
     console.warn("Special event Pokémon unavailable",err);
     return false;
   }
 })();
 try{return await specialEventPokemonLoading}
 finally{specialEventPokemonLoading=null;renderPokemonSpecialEvents()}
}
