 box.innerHTML='<h3>Admin • Special Events</h3><div class="muted">Add or remove this exact Pokémon entry from an event.</div>';
 if(!specialEvents.length){box.insertAdjacentHTML("beforeend",'<div class="muted" style="margin-top:10px">No special events available. Refresh Events in Settings to try again.</div>');return}
 if(!specialEventPokemonLoaded){
