}
async function togglePokemonSpecialEvent(pokemonId,eventSlug){
 if(!isAdmin||publicMode)return toast("Admin access required");
 if(specialEventPokemonSaving)return;
 const p=all().find(x=>String(x.id)===String(pokemonId));
 const catalogSlug=catalogSlugForPokemon(p);
 if(!catalogSlug||!specialEventBySlug(eventSlug)||!specialEventPokemonLoaded)return toast("Event Pokémon unavailable. Refresh Events and try again.");
 const remove=specialEventPokemonHas(eventSlug,catalogSlug);
 specialEventPokemonSaving=true;renderPokemonSpecialEvents();
 try{
   let result;
   if(remove){
     result=await sb.from("special_event_pokemon").delete().eq("event_slug",eventSlug).eq("catalog_slug",catalogSlug).select("event_slug,catalog_slug");
   }else{
     result=await sb.from("special_event_pokemon").insert({event_slug:eventSlug,catalog_slug:catalogSlug,created_by:user.id}).select("event_slug,catalog_slug");
   }
   if(result.error&&!(result.error.code==="23505"&&!remove))throw result.error;
   if(!await loadSpecialEventPokemon())throw new Error("Could not verify event membership");
   if(specialEventPokemonHas(eventSlug,catalogSlug)===remove)throw new Error("Event membership was not changed");
   toast(remove?"Pokémon removed from event":"Pokémon added to event");
 }catch(err){
   console.error("Could not update event Pokémon",err);
   toast("Could not confirm event Pokémon update. Refresh Events and try again.");
 }finally{specialEventPokemonSaving=false;renderPokemonSpecialEvents()}
}
